        const name = this.encoder.encode(String(cName));
        const data = bytes === null || bytes === undefined ? null : DgxUiPreview.bytesView(bytes);
        if (bytes !== null && bytes !== undefined && !data) return {code: -3, offset: 0, name: '', said: `${cName}: no bytes`};
